	SetNpcActionFile("独孤剑",0,"npc001_st2.asf");
	SetNpcActionFile("独孤剑",1,"npc001_sst2.asf");
	SetPlayerState(0);
	Sleep(800);
	Say("独孤剑：琳儿！杨姑娘——", 10);
	PlayerRunTo(12,12);
	SetPlayerDir(5);
	
	FadeOut();
	LoadMap("map111_成都北郊.map");
