traps.Trap02.txt:
//打开密门的trap

	If ($Clue == 110) @Clue110;
	
	Return;
	
@Clue110:
	Say("独孤剑：这是什么？", 8);
	PlayerGoto(27,39);
	SetPlayerDir(5);
	Say("墙上有金属制成的五柄颜色不同的小剑，剑身微微凸出墙面，似乎可以按下去。");
	Say("独孤剑：这应该就是开密门的机关了。", 2);
	
	Choose("独孤剑：第一柄红剑，按下吗","A 按","B 不按",$Choose);
	If ($Choose == 0) @Choose1;
	If ($Choose == 1) @Choose2;
  @Choose1:
	Assign($Mimen, 2);
	Goto @Lable2;
  @Choose2:
 	Assign($Mimen, 1);
 	Goto @Lable2;
 	
@Lable2:
	Choose("独孤剑：第二柄白剑……","A 按","B 不按",$Choose);
	If ($Choose == 0) @Choose3;
	If ($Choose == 1) @Choose4;
  @Choose3:
 	Add($Mimen, 10);
	Goto @Lable3;
  @Choose4:
 	Add($Mimen, 20);
 	Goto @Lable3;
	
@Lable3:
	Choose("独孤剑：第三柄青剑……","A 按","B 不按",$Choose);
	If ($Choose == 0) @Choose5;
	If ($Choose == 1) @Choose6;
  @Choose5:
	Add($Mimen, 100);
	Goto @Lable4;
  @Choose6:
 	Add($Mimen, 200);
	Goto @Lable4;
	
@Lable4:
	Choose("独孤剑：第四柄黄剑……","A 按","B 不按",$Choose);
	If ($Choose == 0) @Choose7;
	If ($Choose == 1) @Choose8;
  @Choose7:
	Add($Mimen, 1000);
	Goto @Lable5;
  @Choose8:
 	Add($Mimen, 2000);
	Goto @Lable5;
	
@Lable5:
	Choose("独孤剑：第五柄紫剑……","A 按","B 不按",$Choose);
	If ($Choose == 0) @Choose9;
	If ($Choose == 1) @Choose10;
  @Choose9:
  	Add($Mimen, 20000);
  	Goto @End;
  @Choose10:
  	Add($Mimen, 10000);
  	Goto @End;

@End:
	FadeOut();
	LoadMap("map113_五剑堂正厅.map");
	LoadNpc("map113.npc");
	LoadObj("map113.obj");
	SetPlayerPos(27,40);
	SetPlayerDir(2);
	FadeIn();
	Sleep(500);
	Say("“嘎嘎嘎——”墙那边传来机械的声响。");
	
	Say("独孤剑：果然是了！", 1);
	Assign($Clue, 120);
	Memo("在五剑堂的墙壁上发现一道机关，按下以后，密门打开。");
	Return;

