traps.trap03.txt:
//进入密室内后

	MoveScreen(4,100,2);
	Say("独孤剑：琳心！", 6);
	PlayerRunTo(9,16);
	SetPlayerDir(5);
	
	NpcAttack("林对儿", 9, 16);
