	SetNpcRes("林对儿", "npcres041_林对儿.ini");
	Say("独孤剑：原来是你！", 10);
	Say("林对儿：怎么样，现在后悔当初在华山没有把我杀掉了吧。当日你给我的羞辱，今天姓林的要十倍奉还！",98);
	Say("独孤剑：就凭你？", 10);
	Say("无相：独孤少侠莫非忘记了老夫，呵呵。", 73);
	AddNpc("npc042_成都无相和尚.ini",7,11,7); 
	Say("封玉书：独孤剑，今天你是插翅也难飞了！", 64);
	AddNpc("npc026_成都封玉书.ini",7,21,5);
	Sleep(500);
	
	SetNpcActionFile("独孤剑", 0, "npc001_st.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst.asf");
	NpcSpecialAction("独孤剑", "mpc034_3.asf");
	Sleep(1000);
	
	SetPlayerDir(0);
	MoveScreen(0,70,2);
	PlaySound("特_石门.wav");
	OpenBox("关上的门");
	Sleep(2000);
	AddObj("门类障碍.ini",9,30,0);
	AddObj("门类障碍.ini",8,31,0);
	
	SetPlayerScn();
	Sleep(500);
	Say("独孤剑：……", 10);
	Say("林对儿：哼，你也有怕的时候。",98);
	SetPlayerDir(5);
	Say("独孤剑：你们把张姑娘和杨姑娘怎么了！", 10);
	Say("林对儿：独孤剑，我真佩服你，到现在还想着拈花惹草……",98);
	Say("林对儿：当日在华山下，这两个臭丫头要怎么对付我，哼哼，我现在就怎么对付她们……",98);
	
	PlaySound("特_石门.wav");
	OpenBox("打开的门");
	Sleep(1000);
	Say("独孤剑：琳心！",10);
	Say("林对儿：我要在你面前，慢慢地凌辱她们……哈哈哈哈——", 98);
	Say("独孤剑：无耻小人！我要杀了你们。", 10);
	Say("无相：哼哼，我们三个特地为独孤大侠准备好了这个“真魔三劫阵”。独孤大侠不要让我们失望哦……", 73);
	SetNpcRelation("林对儿",1);
	SetNpcRelation("无相和尚",1);
	SetNpcRelation("封玉书",1);
	SetPlayerScn();
	SetNpcDeathScript("独孤剑", "主角死亡.txt");
	SetMapTrap(03,"");
	Assign($Clue, 130);
	Memo("进入密室后，独孤剑救人心切，中了林对儿的暗算，而等待他的正是由五色教三位堂主精心准备的“真魔三劫阵”。");
	Return;

